<?php require_once __DIR__.'/includes/config.php';require_login();require_permission('expenses');$uid=(int)$_SESSION['user_id'];$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);$date=$_POST['expense_date']??date('Y-m-d');$dt=DateTime::createFromFormat('Y-m-d',$date);if($title===''||mb_strlen($title)>160)$errors[]='Enter an expense description.';if($amount===false||$amount<=0)$errors[]='Enter an amount greater than zero.';if(!$dt||$dt->format('Y-m-d')!==$date)$errors[]='Enter a valid expense date.';if(!$errors){$q=$pdo->prepare('INSERT INTO expenses(user_id,title,amount,expense_date) VALUES(?,?,?,?)');$q->execute([$uid,$title,$amount,$date]);audit_log($pdo,'expense_recorded','expense',(int)$pdo->lastInsertId(),'Amount '.number_format((float)$amount,2,'.','').' NGN; date '.$date);flash('Expense saved.');redirect('expenses.php');}}$q=$pdo->prepare('SELECT * FROM expenses WHERE user_id=? ORDER BY expense_date DESC,id DESC LIMIT 100');$q->execute([$uid]);$rows=$q->fetchAll();$pageTitle='Expenses';require __DIR__.'/includes/header.php';?><div class="page-heading"><div><h1 class="h3 fw-bold mb-1">Business expenses</h1><p class="muted mb-0">Record rent, transport, utilities, supplies, and other costs.</p></div></div><?php foreach($errors as $err):?><div class="alert alert-danger"><?=e($err)?></div><?php endforeach;?><div class="row g-4"><div class="col-lg-4"><div class="card"><div class="card-body p-4"><h2 class="h5 fw-bold mb-3">Add expense</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label">Description</label><input class="form-control" name="title" maxlength="160" required></div><div class="mb-3"><label class="form-label">Amount (₦)</label><input class="form-control" type="number" min="0.01" step="0.01" name="amount" required></div><div class="mb-3"><label class="form-label">Date</label><input class="form-control" type="date" name="expense_date" value="<?=date('Y-m-d')?>" required></div><button class="btn btn-primary">Save expense</button></form></div></div></div><div class="col-lg-8"><div class="card"><div class="card-body"><h2 class="h5 fw-bold mb-3">Recent expenses</h2><div class="table-responsive"><table class="table"><thead><tr><th>Description</th><th>Date</th><th>Amount</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['expense_date'])?></td><td><?=money($r['amount'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty-state">No expenses recorded yet.</div><?php endif;?></div></div></div></div></div><?php require __DIR__.'/includes/footer.php';?>
